        result = alloc_sg_list_from_pages(&um->sgt.sgl, pages, page_count,
                                      addr & ~PAGE_MASK, size, &um->sgt.nents);

        um->sgt.orig_nents = um->sgt.nents;
#endif
        if (unlikely(result < 0)) {
            pr_warn("[galcore]: %s: sg_alloc_table_from_pages failed\n", __func__);
            goto error;
        }

        result = dma_map_sg(dev, um->sgt.sgl, um->sgt.nents, DMA_TO_DEVICE);
        if (unlikely(result != um->sgt.nents)) {
            pr_warn("[galcore]: %s: dma_map_sg failed\n", __func__);
            goto error;
        }

        if (Os->iommu)
            um->dmaHandle = sg_dma_address(um->sgt.sgl);

        dma_sync_sg_for_cpu(dev, um->sgt.sgl, um->sgt.nents, DMA_FROM_DEVICE);
    }

    um->type  = UM_PAGE_MAP;
    um->pages = pages;

    return 0;

error:
#if gcdUSE_LINUX_SG_TABLE_API
    sg_free_table(&um->sgt);
#else
    kfree(um->sgt.sgl);
#endif

    kfree(pages);

    return result;
}

static int
import_page_map(gckOS           Os,
                struct device  *dev,
                struct um_desc *um,
                unsigned long   addr,
                size_t          page_count,
                size_t          size,
                unsigned long   flags)
{
    printk(KERN_INFO "FUNC_ENTRY: Entering function import_page_map at %s:%d\n", __FILE__, __LINE__);
    int           i;
    int           result;
    struct page **pages;

    if ((addr & (cache_line_size() - 1)) || (size & (cache_line_size() - 1)))
        /* Not cpu cacheline size aligned, can not support. */
        return -EINVAL;

    pages = kcalloc(page_count, sizeof(void *), GFP_KERNEL | gcdNOWARN);
    if (!pages)
        return -ENOMEM;

    down_read(&current_mm_mmap_sem);

#if LINUX_VERSION_CODE > KERNEL_VERSION(5, 6, 0)
    result = pin_user_pages(addr & PAGE_MASK, page_count,
#elif LINUX_VERSION_CODE < KERNEL_VERSION(4, 6, 0)
    result = get_user_pages(current, current->mm, addr & PAGE_MASK, page_count,
#else
    result = get_user_pages(addr & PAGE_MASK, page_count,
#endif
#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 9, 0) || defined(CONFIG_PPC)
                            (flags & VM_WRITE) ? FOLL_WRITE : 0,
#else
                            (flags & VM_WRITE) ? 1 : 0, 0,
#endif
#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 4, 0)
                            pages);
#else
                            pages, NULL);
#endif

    up_read(&current_mm_mmap_sem);

    if (result < page_count) {
        for (i = 0; i < result; i++) {
            if (pages[i])
#if LINUX_VERSION_CODE > KERNEL_VERSION(5, 6, 0)
                unpin_user_page(pages[i]);
#else
                put_page(pages[i]);
#endif
        }

        kfree(pages);
        return -ENODEV;
    }

    um->chunk_count = 1;
    for (i = 1; i < page_count; i++) {
        if (page_to_pfn(pages[i]) != page_to_pfn(pages[i - 1]) + 1)
            ++um->chunk_count;
    }

    if (gcmIS_SUCCESS(phy_is_from_reserved(Os, (gctPHYS_ADDR_T)page_to_pfn(pages[0]) << PAGE_SHIFT)))
        um->alloc_from_res = 1;

    printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_sync_sg_for_cpu from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_sync_sg_for_cpu called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_sync_sg_for_cpu\n");
    printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_map_sg from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_map_sg called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_map_sg\n");
    if (!um->alloc_from_res) {
#if gcdUSE_LINUX_SG_TABLE_API
        result = sg_alloc_table_from_pages(&um->sgt, pages, page_count,
                                           addr & ~PAGE_MASK, size,
                                           GFP_KERNEL | gcdNOWARN);

#else
        result = alloc_sg_list_from_pages(&um->sgt.sgl, pages, page_count,
                                      addr & ~PAGE_MASK, size, &um->sgt.nents);

        um->sgt.orig_nents = um->sgt.nents;
#endif
        if (unlikely(result < 0)) {
            pr_warn("[galcore]: %s: sg_alloc_table_from_pages failed\n", __func__);
            goto error;
        }

        result = dma_map_sg(dev, um->sgt.sgl, um->sgt.nents, DMA_TO_DEVICE);
        if (unlikely(result != um->sgt.nents)) {
            pr_warn("[galcore]: %s: dma_map_sg failed\n", __func__);
            goto error;
        }

        if (Os->iommu)
            um->dmaHandle = sg_dma_address(um->sgt.sgl);

        dma_sync_sg_for_cpu(dev, um->sgt.sgl, um->sgt.nents, DMA_FROM_DEVICE);
    }

    um->type  = UM_PAGE_MAP;
    um->pages = pages;

    return 0;

error:
#if gcdUSE_LINUX_SG_TABLE_API
    sg_free_table(&um->sgt);
#else
    kfree(um->sgt.sgl);
#endif

    kfree(pages);

    return result;
}

static gceSTATUS
_UserMemoryCache(IN gckALLOCATOR      Allocator,
                 IN PLINUX_MDL        Mdl,
                 IN gctSIZE_T         Offset,
                 IN gctPOINTER        Logical,
                 IN gctSIZE_T         Bytes,
                 IN gceCACHEOPERATION Operation)
{
    printk(KERN_INFO "FUNC_ENTRY: Entering function _UserMemoryCache at %s:%d\n", __FILE__, __LINE__);
    struct um_desc         *um  = Mdl->priv;
    enum dma_data_direction dir;
    struct device          *dev = (struct device *)Mdl->device;

    if (um->type == UM_PHYSICAL_MAP || um->alloc_from_res) {
        _MemoryBarrier();
        return gcvSTATUS_OK;
    }

    if (um->type == UM_PFN_MAP && um->pfns_valid == 0) {
        _MemoryBarrier();
        return gcvSTATUS_OK;
    }

#ifdef CONFIG_ARM
    /* coherent cache in case vivt or vipt-aliasing cache. */
    __cpuc_flush_user_range(um->user_vaddr,
                            um->user_vaddr + um->size,
                            um->vm_flags);
#endif

    switch (Operation) {
    case gcvCACHE_CLEAN:
        dir = DMA_TO_DEVICE;
        printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_sync_sg_for_device from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_sync_sg_for_device called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_sync_sg_for_device\n");
        dma_sync_sg_for_device(dev, um->sgt.sgl, um->sgt.nents, dir);
        break;
    case gcvCACHE_FLUSH:
        dir = DMA_TO_DEVICE;
        printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_sync_sg_for_device from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_sync_sg_for_device called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_sync_sg_for_device\n");
        dma_sync_sg_for_device(dev, um->sgt.sgl, um->sgt.nents, dir);
        dir = DMA_FROM_DEVICE;
        printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_sync_sg_for_cpu from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_sync_sg_for_cpu called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_sync_sg_for_cpu\n");
        dma_sync_sg_for_cpu(dev, um->sgt.sgl, um->sgt.nents, dir);
        break;
    case gcvCACHE_INVALIDATE:
        dir = DMA_FROM_DEVICE;
        printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_sync_sg_for_cpu from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_sync_sg_for_cpu called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_sync_sg_for_cpu\n");
        dma_sync_sg_for_cpu(dev, um->sgt.sgl, um->sgt.nents, dir);
        break;
    default:
        return gcvSTATUS_INVALID_ARGUMENT;
    }

    return gcvSTATUS_OK;
}

